  _globals['_INTERCEPTORSERVICE'].methods_by_name['UpsertTokenTemplate']._loaded_options = None
  _globals['_INTERCEPTORSERVICE'].methods_by_name['UpsertTokenTemplate']._serialized_options = b'\222A\346\004\n\014Interceptors\022 Create or replace token template\032\370\002Creates or replaces the token template for the environment. The template is validated for syntax, claim count, and restricted keys before being persisted. If an ACCESS_TOKEN_CREATION interceptor already exists, its template is updated in place and the enabled state is preserved. If none exists, a new disabled interceptor is created. Returns the saved template configuration.Je\n\003200\022^\n!Token template saved successfully\0229\n7\0325.scalekit.v1.interceptors.UpsertTokenTemplateResponseJR\n\003400\022K\nIInvalid template \342\200\224 syntax error, restricted key, or exceeds claim limit\202\265\030\002\030D\372\322\344\223\002\t\022\007PREVIEW\202\323\344\223\002\034\032\027/api/v1/token-templates:\001*'
  _globals['_INTERCEPTORSERVICE'].methods_by_name['GetTokenTemplate']._loaded_options = None
  _globals['_INTERCEPTORSERVICE'].methods_by_name['GetTokenTemplate']._serialized_options = b'\222A\301\002\n\014Interceptors\022\027Retrieve token template\032kReturns the currently saved token template for the environment, including its enabled state and timestamps.Jf\n\003200\022_\n%Token template retrieved successfully\0226\n4\0322.scalekit.v1.interceptors.GetTokenTemplateResponseJC\n\003404\022<\n:No token template has been configured for this environment\202\265\030\002\030D\372\322\344\223\002\t\022\007PREVIEW\202\323\344\223\002\031\022\027/api/v1/token-templates'
