  _globals['_INTERCEPTORSERVICE'].methods_by_name['DeleteTokenTemplate']._serialized_options = b'\222A\304\002\n\014Interceptors\022\025Delete token template\032\251\001Deletes the token template for the environment. Custom claims stop being added to tokens immediately. A subsequent UpsertTokenTemplate creates a fresh disabled template.J,\n\003200\022%\n#Token template deleted successfullyJC\n\003404\022<\n:No token template has been configured for this environment\202\265\030\002\030D\372\322\344\223\002\t\022\007PREVIEW\202\323\344\223\002\031*\027/api/v1/token-templates'
  _globals['_INTERCEPTORSERVICE'].methods_by_name['EnableTokenTemplate']._loaded_options = None
  _globals['_INTERCEPTORSERVICE'].methods_by_name['EnableTokenTemplate']._serialized_options = b'\222A\201\003\n\014Interceptors\022\025Enable token template\032\236\001Activates the token template so it begins affecting issued access tokens. The template must have been saved with UpsertTokenTemplate before it can be enabled.J,\n\003200\022%\n#Token template enabled successfullyJF\n\003400\022?\n=No template has been saved \342\200\224 call UpsertTokenTemplate firstJC\n\003404\022<\n:No token template has been configured for this environment\202\265\030\002\030D\372\322\344\223\002\t\022\007PREVIEW\202\323\344\223\002 2\036/api/v1/token-templates:enable'
  _globals['_INTERCEPTORSERVICE'].methods_by_name['DisableTokenTemplate']._loaded_options = None
  _globals['_INTERCEPTORSERVICE'].methods_by_name['DisableTokenTemplate']._serialized_options = b'\222A\244\002\n\014Interceptors\022\026Disable token template\032\207\001Deactivates the token template so it stops affecting issued access tokens. The saved template is preserved and can be re-enabled later.J-\n\003200\022&\n$Token template disabled successfullyJC\n\003404\022<\n:No token template has been configured for this environment\202\265\030\002\030D\372\322\344\223\002\t\022\007PREVIEW\202\323\344\223\002!2\037/api/v1/token-templates:disable'
  _globals['_INTERCEPTORSERVICE'].methods_by_name['PreviewTokenTemplate']._loaded_options = None
  _globals['_INTERCEPTORSERVICE'].methods_by_name['PreviewTokenTemplate']._serialized_options = b'\222A\217\005\n\014Interceptors\022\026Preview token template\032\260\002Evaluates an inline token template against real user and organization data without saving it. Use this to verify that your template produces the expected claims before saving. Evaluation errors are returned in the response body rather than as HTTP errors \342\200\224 check the error field even on a 200 response.J\232\001\n\003200\022\222\001\nTTemplate evaluated; resolved claims, omitted keys, and any evaluation error returned\022:\n8\0326.scalekit.v1.interceptors.PreviewTokenTemplateResponseJh\n\003400\022a\n_Template is not valid JSON, contains an expression syntax error, or uses a restricted claim keyJ-\n\003404\022&\n$User not found for the given user_id\202\265\030\002\030D\372\322\344\223\002\t\022\007PREVIEW\202\323\344\223\002$\"\037/api/v1/token-templates/preview:\001*'
  _globals['_INTERCEPTORSERVICE'].methods_by_name['GetTokenTemplateContext']._loaded_options = None
  _globals['_INTERCEPTORSERVICE'].methods_by_name['GetTokenTemplateContext']._serialized_options = b'\222A\200\004\n\014Interceptors\022%List token template context variables\032\302\002Returns the full schema of variables available inside a token template \342\200\224 user, organization, m2m_token_claims, and interceptor_context \342\200\224 with field names and types. Derived from the actual runtime data model, so it always reflects the current set of available keys. Use this to power autocomplete in a template editor.J\203\001\n\003200\022|\n;Available template variables and their nested field schemas\022=\n;\0329.scalekit.v1.interceptors.GetTokenTemplateContextResponse\202\265\030\002\030D\372\322\344\223\002\t\022\007PREVIEW\202\323\344\223\002!\022\037/api/v1/token-templates/context'
